///////////////////////////////////////////////////////////////////////
/// GS_Cheat
///////////////////////////////////////////////////////////////////////

GS_Cheat::GS_Cheat() :
	m_pMenuMain( NULL )
{
}

GS_Cheat::~GS_Cheat()
{
}

///////////////////////////////////////////////////////////////////////

void GS_Cheat::ctor()
{
	m_TE.SetTapDetectionEnabled( true );
	m_TE.SetEnabled( true );
	m_TE.SetScreenCoordinates(0, 0, 480, 320);
}

void GS_Cheat::dtor()
{
}

///////////////////////////////////////////////////////////////////////

void GS_Cheat::pause()
{	
}

void GS_Cheat::resume()
{
}

///////////////////////////////////////////////////////////////////////

void GS_Cheat::update( float dt )
{
	if( m_TE.IsNowActivated() )
	{
		s32 x, y;

		m_TE.GetTouchPos_Current( x, y );

		if( __CHEATS()->Activate( x, y ) )
		{
			__CHEATS()->Hide();
			__CHEATS()->Clear();
			__MGR_STATES()->popState();
		}
	}
}

void GS_Cheat::draw()
{
	__IRR_DRIVER()->beginScene2D();

	__CHEATS()->Draw();

	__IRR_DRIVER()->endScene2D();
}

